for (const s of process.argv.slice(2)) {
  const p = await b.newPage({ viewport: { width: 390, height: 844 } });
  const err=[]; p.on("pageerror", e=>err.push(e.message));
  const r = await p.goto("http://localhost:3100/ratgeber/" + s, { waitUntil: "domcontentloaded", timeout: 180000 });
  await p.waitForTimeout(3000);
  const info = await p.evaluate(() => {
    const vw = document.documentElement.clientWidth;
    const bad = [...document.querySelectorAll("main *")].filter(e => { const rc = e.getBoundingClientRect(); if (rc.right <= vw + 1) return false; let a = e.parentElement; while (a) { const st = getComputedStyle(a); if (["auto","scroll","hidden"].includes(st.overflowX)) return false; a = a.parentElement; } return true; }).slice(0,5).map(e=>e.tagName+"."+e.className.toString().slice(0,40));
    return { sw: document.documentElement.scrollWidth, vw, bad, lese: (document.body.innerText.match(/(\d+) Min\. Lesezeit/)||[])[1] };
  });
  // Tabellen-Ausschnitt screenshot
  const t = await p.$("table"); if (t) { await t.scrollIntoViewIfNeeded(); await p.waitForTimeout(500); await p.screenshot({ path: fileURLToPath(new URL(`./shots/${s}_tab390.png`, import.meta.url)) }); }
  console.log(s, r.status(), JSON.stringify(info), err.join(" | "));
  await p.close();
}
await b.close();
EOF
